  1→import { execFileSync } from "node:child_process";
  2→import * as fs from "node:fs";
  3→import * as path from "node:path";
  4→import { input, select } from "@inquirer/prompts";
  5→import type { Config, ConfigManager } from "./config.js";
  6→
  7→// --- ANSI colors ---
  8→
  9→const c = {
 10→  reset: "\x1b[0m",
 11→  bold: "\x1b[1m",
 12→  dim: "\x1b[2m",
 13→  green: "\x1b[32m",
 14→  yellow: "\x1b[33m",
 15→  red: "\x1b[31m",
 16→  cyan: "\x1b[36m",
 17→  white: "\x1b[37m",
 18→};
 19→
 20→const ok = (msg: string) =>
 21→  `${c.green}${c.bold}✓${c.reset} ${c.green}${msg}${c.reset}`;
 22→const warn = (msg: string) => `${c.yellow}⚠ ${msg}${c.reset}`;
 23→const fail = (msg: string) => `${c.red}✗ ${msg}${c.reset}`;
 24→const step = (n: number, title: string) =>
 25→  `\n${c.cyan}${c.bold}[${n}/3]${c.reset} ${c.bold}${title}${c.reset}\n`;
 26→const dim = (msg: string) => `${c.dim}${msg}${c.reset}`;
 27→
 28→// --- Telegram validation ---
 29→
 30→export async function validateBotToken(
 31→  token: string,
 32→): Promise<
 33→  | { ok: true; botName: string; botUsername: string }
 34→  | { ok: false; error: string }
 35→> {
 36→  try {
 37→    const res = await fetch(`https://api.telegram.org/bot${token}/getMe`);
 38→    const data = (await res.json()) as {
 39→      ok: boolean;
 40→      result?: { first_name: string; username: string };
 41→      description?: string;
 42→    };
 43→    if (data.ok && data.result) {
 44→      return {
 45→        ok: true,
 46→        botName: data.result.first_name,
 47→        botUsername: data.result.username,
 48→      };
 49→    }
 50→    return { ok: false, error: data.description || "Invalid token" };
 51→  } catch (err) {
 52→    return { ok: false, error: (err as Error).message };
 53→  }
 54→}
 55→
 56→export async function validateChatId(
 57→  token: string,
 58→  chatId: number,
 59→): Promise<
 60→  { ok: true; title: string; isForum: boolean } | { ok: false; error: string }
 61→> {
 62→  try {
 63→    const res = await fetch(`https://api.telegram.org/bot${token}/getChat`, {
 64→      method: "POST",
 65→      headers: { "Content-Type": "application/json" },
 66→      body: JSON.stringify({ chat_id: chatId }),
 67→    });
 68→    const data = (await res.json()) as {
 69→      ok: boolean;
 70→      result?: { title: string; type: string; is_forum?: boolean };
 71→      description?: string;
 72→    };
 73→    if (!data.ok || !data.result) {
 74→      return { ok: false, error: data.description || "Invalid chat ID" };
 75→    }
 76→    if (data.result.type !== "supergroup") {
 77→      return {
 78→        ok: false,
 79→        error: `Chat is "${data.result.type}", must be a supergroup`,
 80→      };
 81→    }
 82→    return {
 83→      ok: true,
 84→      title: data.result.title,
 85→      isForum: data.result.is_forum === true,
 86→    };
 87→  } catch (err) {
 88→    return { ok: false, error: (err as Error).message };
 89→  }
 90→}
 91→
 92→// --- Chat ID auto-detection ---
 93→
 94→function promptManualChatId(): Promise<number> {
 95→  return input({
 96→    message: "Supergroup chat ID (e.g. -1001234567890):",
 97→    validate: (val) => {
 98→      const n = Number(val.trim());
 99→      if (isNaN(n) || !Number.isInteger(n)) return "Chat ID must be an integer";
100→      return true;
101→    },
102→  }).then((val) => Number(val.trim()));
103→}
104→
105→async function detectChatId(token: string): Promise<number> {
106→  // Clear old updates
107→  let lastUpdateId = 0;
108→  try {
109→    const clearRes = await fetch(
110→      `https://api.telegram.org/bot${token}/getUpdates?offset=-1`,
111→    );
112→    const clearData = (await clearRes.json()) as {
113→      ok: boolean;
114→      result?: Array<{ update_id: number }>;
115→    };
116→    if (clearData.ok && clearData.result?.length) {
117→      lastUpdateId = clearData.result[clearData.result.length - 1].update_id;
118→    }
119→  } catch {
120→    // ignore
121→  }
122→
123→  console.log("");
124→  console.log(`  ${c.bold}If you don't have a supergroup yet:${c.reset}`);
125→  console.log(dim("  1. Open Telegram → New Group → add your bot"));
126→  console.log(dim("  2. Group Settings → convert to Supergroup"));
127→  console.log(dim("  3. Enable Topics in group settings"));
128→  console.log("");
129→  console.log(`  ${c.bold}Then send "hi" in the group.${c.reset}`);
130→  console.log(
131→    dim(
132→      `  Listening... press ${c.reset}${c.yellow}m${c.reset}${c.dim} to enter ID manually`,
133→    ),
134→  );
135→  console.log("");
136→
137→  const MAX_ATTEMPTS = 120;
138→  const POLL_INTERVAL = 1000;
139→
140→  // Listen for 'm' keypress to switch to manual
141→  let cancelled = false;
142→  const onKeypress = (data: Buffer) => {
143→    const key = data.toString();
144→    if (key === "m" || key === "M") {
145→      cancelled = true;
146→    }
147→  };
148→  if (process.stdin.isTTY) {
149→    process.stdin.setRawMode(true);
150→    process.stdin.resume();
151→    process.stdin.on("data", onKeypress);
152→  }
153→
154→  const cleanup = () => {
155→    if (process.stdin.isTTY) {
156→      process.stdin.removeListener("data", onKeypress);
157→      process.stdin.setRawMode(false);
158→      process.stdin.pause();
159→    }
160→  };
161→
162→  try {
163→    for (let i = 0; i < MAX_ATTEMPTS; i++) {
164→      if (cancelled) {
165→        cleanup();
