 28→// --- Telegram validation ---
 29→
 30→export async function validateBotToken(
 31→  token: string,
 32→): Promise<
 33→  | { ok: true; botName: string; botUsername: string }
 34→  | { ok: false; error: string }
 35→> {
 36→  try {
 37→    const res = await fetch(`https://api.telegram.org/bot${token}/getMe`);
 38→    const data = (await res.json()) as {
 39→      ok: boolean;
 40→      result?: { first_name: string; username: string };
 41→      description?: string;
 42→    };
 43→    if (data.ok && data.result) {
 44→      return {
 45→        ok: true,
 46→        botName: data.result.first_name,
 47→        botUsername: data.result.username,
 48→      };
 49→    }
 50→    return { ok: false, error: data.description || "Invalid token" };
 51→  } catch (err) {
 52→    return { ok: false, error: (err as Error).message };
 53→  }
 54→}
 55→
 56→export async function validateChatId(
 57→  token: string,
 58→  chatId: number,
 59→): Promise<
 60→  { ok: true; title: string; isForum: boolean } | { ok: false; error: string }
 61→> {
 62→  try {
 63→    const res = await fetch(`https://api.telegram.org/bot${token}/getChat`, {
 64→      method: "POST",
 65→      headers: { "Content-Type": "application/json" },
 66→      body: JSON.stringify({ chat_id: chatId }),
 67→    });
 68→    const data = (await res.json()) as {
 69→      ok: boolean;
 70→      result?: { title: string; type: string; is_forum?: boolean };
 71→      description?: string;
 72→    };
 73→    if (!data.ok || !data.result) {
 74→      return { ok: false, error: data.description || "Invalid chat ID" };
 75→    }
 76→    if (data.result.type !== "supergroup") {
 77→      return {
 78→        ok: false,
 79→        error: `Chat is "${data.result.type}", must be a supergroup`,
 80→      };
 81→    }
 82→    return {
 83→      ok: true,
 84→      title: data.result.title,
 85→      isForum: data.result.is_forum === true,
 86→    };
 87→  } catch (err) {
 88→    return { ok: false, error: (err as Error).message };
 89→  }
 90→}
