105→async function detectChatId(token: string): Promise<number> {
106→  // Clear old updates
107→  let lastUpdateId = 0;
108→  try {
109→    const clearRes = await fetch(
110→      `https://api.telegram.org/bot${token}/getUpdates?offset=-1`,
111→    );
112→    const clearData = (await clearRes.json()) as {
113→      ok: boolean;
114→      result?: Array<{ update_id: number }>;
115→    };
116→    if (clearData.ok && clearData.result?.length) {
117→      lastUpdateId = clearData.result[clearData.result.length - 1].update_id;
118→    }
119→  } catch {
120→    // ignore
121→  }
122→
123→  console.log("");
124→  console.log(`  ${c.bold}If you don't have a supergroup yet:${c.reset}`);
125→  console.log(dim("  1. Open Telegram → New Group → add your bot"));
126→  console.log(dim("  2. Group Settings → convert to Supergroup"));
127→  console.log(dim("  3. Enable Topics in group settings"));
128→  console.log("");
129→  console.log(`  ${c.bold}Then send "hi" in the group.${c.reset}`);
130→  console.log(
131→    dim(
132→      `  Listening... press ${c.reset}${c.yellow}m${c.reset}${c.dim} to enter ID manually`,
133→    ),
134→  );
135→  console.log("");
136→
137→  const MAX_ATTEMPTS = 120;
138→  const POLL_INTERVAL = 1000;
139→
140→  // Listen for 'm' keypress to switch to manual
141→  let cancelled = false;
142→  const onKeypress = (data: Buffer) => {
143→    const key = data.toString();
144→    if (key === "m" || key === "M") {
145→      cancelled = true;
146→    }
147→  };
148→  if (process.stdin.isTTY) {
149→    process.stdin.setRawMode(true);
150→    process.stdin.resume();
151→    process.stdin.on("data", onKeypress);
152→  }
153→
154→  const cleanup = () => {
155→    if (process.stdin.isTTY) {
156→      process.stdin.removeListener("data", onKeypress);
157→      process.stdin.setRawMode(false);
158→      process.stdin.pause();
159→    }
160→  };
161→
162→  try {
163→    for (let i = 0; i < MAX_ATTEMPTS; i++) {
164→      if (cancelled) {
165→        cleanup();
166→        return promptManualChatId();
167→      }
168→
169→      try {
170→        const offset = lastUpdateId ? lastUpdateId + 1 : 0;
171→        const res = await fetch(
172→          `https://api.telegram.org/bot${token}/getUpdates?offset=${offset}&timeout=1`,
173→        );
174→        const data = (await res.json()) as {
175→          ok: boolean;
176→          result?: Array<{
177→            update_id: number;
178→            message?: {
179→              chat: { id: number; title?: string; type: string };
180→            };
181→            my_chat_member?: {
182→              chat: { id: number; title?: string; type: string };
183→            };
184→          }>;
185→        };
186→
187→        if (!data.ok || !data.result?.length) {
188→          await new Promise((r) => setTimeout(r, POLL_INTERVAL));
189→          continue;
190→        }
191→
192→        const groups = new Map<number, string>();
193→        for (const update of data.result) {
194→          lastUpdateId = update.update_id;
195→          const chat = update.message?.chat ?? update.my_chat_member?.chat;
196→          if (chat && (chat.type === "supergroup" || chat.type === "group")) {
197→            groups.set(chat.id, chat.title ?? String(chat.id));
198→          }
199→        }
200→
201→        if (groups.size === 1) {
202→          const [id, title] = [...groups.entries()][0];
203→          console.log(
204→            ok(`Group detected: ${c.bold}${title}${c.reset}${c.green} (${id})`),
205→          );
206→          cleanup();
207→          return id;
208→        }
209→
210→        if (groups.size > 1) {
211→          cleanup();
212→          const choices = [...groups.entries()].map(([id, title]) => ({
213→            name: `${title} (${id})`,
214→            value: id,
215→          }));
216→          return select({
217→            message: "Multiple groups found. Pick one:",
218→            choices,
219→          });
220→        }
221→      } catch {
222→        // Network error, retry
223→      }
224→      await new Promise((r) => setTimeout(r, POLL_INTERVAL));
225→    }
226→
227→    console.log(warn("Timed out waiting for messages."));
228→    cleanup();
229→    return promptManualChatId();
230→  } catch (err) {
231→    cleanup();
232→    throw err;
233→  }
234→}
