236→// --- Agent detection ---
237→
238→const KNOWN_AGENTS: Array<{ name: string; commands: string[] }> = [
239→  { name: "claude", commands: ["claude-agent-acp"] },
240→];
241→
242→function commandExists(cmd: string): boolean {
243→  try {
244→    execFileSync("which", [cmd], { stdio: "pipe" });
245→    return true;
246→  } catch {
247→    // not in PATH
248→  }
249→  let dir = process.cwd();
250→  while (true) {
251→    const binPath = path.join(dir, "node_modules", ".bin", cmd);
252→    if (fs.existsSync(binPath)) return true;
253→    const parent = path.dirname(dir);
254→    if (parent === dir) break;
255→    dir = parent;
256→  }
257→  return false;
258→}
259→
260→export async function detectAgents(): Promise<
261→  Array<{ name: string; command: string }>
262→> {
263→  const found: Array<{ name: string; command: string }> = [];
264→  for (const agent of KNOWN_AGENTS) {
265→    const available: string[] = [];
266→    for (const cmd of agent.commands) {
267→      if (commandExists(cmd)) {
268→        available.push(cmd);
269→      }
270→    }
271→    if (available.length > 0) {
272→      found.push({ name: agent.name, command: available[0] });
273→    }
274→  }
275→  return found;
276→}
