289→export async function setupTelegram(): Promise<Config["channels"][string]> {
290→  console.log(step(1, "Telegram Bot"));
291→
292→  let botToken = "";
293→
294→  while (true) {
295→    botToken = await input({
296→      message: "Bot token (from @BotFather):",
297→      validate: (val) => val.trim().length > 0 || "Token cannot be empty",
298→    });
299→    botToken = botToken.trim();
300→
301→    const result = await validateBotToken(botToken);
302→    if (result.ok) {
303→      console.log(ok(`Connected to @${result.botUsername}`));
304→      break;
305→    }
306→    console.log(fail(result.error));
307→    const action = await select({
308→      message: "What to do?",
309→      choices: [
310→        { name: "Re-enter token", value: "retry" },
311→        { name: "Use as-is (skip validation)", value: "skip" },
312→      ],
313→    });
314→    if (action === "skip") break;
315→  }
316→
317→  console.log(step(2, "Group Chat"));
318→
319→  const chatId = await detectChatId(botToken);
320→
321→  return {
322→    enabled: true,
323→    botToken,
324→    chatId,
325→    notificationTopicId: null,
326→    assistantTopicId: null,
327→  };
328→}
